package com.retailflow.pos.purchasebill;
import com.retailflow.pos.common.ApiResponse;import java.security.Principal;import java.util.Map;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/purchase-bills") @PreAuthorize("hasAnyRole('OWNER','MANAGER')") public class PurchaseBillController{
 private final PurchaseBillService s;private final PurchaseBillRepository repo;public PurchaseBillController(PurchaseBillService s,PurchaseBillRepository repo){this.s=s;this.repo=repo;}@GetMapping public ApiResponse<?>list(){return ApiResponse.ok(repo.findAll());}@GetMapping("/{id}")public ApiResponse<?>get(@PathVariable String id){return ApiResponse.ok(s.get(id));}@PostMapping public ApiResponse<?>create(@RequestBody PurchaseBill v){return ApiResponse.ok(s.save(v));}@PutMapping("/{id}")public ApiResponse<?>update(@PathVariable String id,@RequestBody PurchaseBill v){v.setId(id);return ApiResponse.ok(s.save(v));}@PostMapping("/{id}/confirm")public ApiResponse<?>confirm(@PathVariable String id,Principal p){return ApiResponse.ok(s.confirm(id,p.getName()));}@PostMapping("/{id}/pay")public ApiResponse<?>pay(@PathVariable String id,@RequestBody PurchaseBillService.PaymentRequest r){return ApiResponse.ok(s.markPaid(id,r));}@DeleteMapping("/{id}")public ApiResponse<Void>delete(@PathVariable String id){repo.deleteById(id);return ApiResponse.ok(null);}@GetMapping("/summary")public ApiResponse<?>summary(){var all=repo.findAll();return ApiResponse.ok(Map.of("totalPayable",all.stream().map(PurchaseBill::getBalanceDue).filter(java.util.Objects::nonNull).reduce(java.math.BigDecimal.ZERO,java.math.BigDecimal::add),"pendingBills",all.stream().filter(b->b.getBalanceDue()!=null&&b.getBalanceDue().signum()>0).count()));}
}
